import { forwardRef, useRef } from 'react';
import { useControllableState } from '../../hooks/useControllableState';

export interface ArvoButtonProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'type' | 'disabled'> {
  variant?: 'primary' | 'secondary' | 'tertiary' | 'outline' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  type?: 'button' | 'submit' | 'reset';
  label: string;
  icon?: string;
  isDisabled?: boolean;
  /**
   * Selected (active) state. Renders the active visual.
   *
   * - When `isToggle` is `false` (default), this is a controlled "active" state
   *   for cases like an active menu trigger. Click does NOT toggle the value.
   * - When `isToggle` is `true`, the button toggles its own state on click. If
   *   `isSelected` is set the parent owns the state; otherwise the button is
   *   uncontrolled and seeds from `defaultSelected`.
   */
  isSelected?: boolean;
  /** Initial selected value when `isToggle` is true and `isSelected` is undefined. */
  defaultSelected?: boolean;
  /**
   * When true, click toggles the selected state and renders `aria-pressed`.
   * The button announces itself as a toggle button to assistive tech.
   */
  isToggle?: boolean;
  /**
   * Fired when the toggle state flips. Only emitted when `isToggle` is true.
   */
  onSelectionChange?: (isSelected: boolean) => void;
  isFullWidth?: boolean;
  isLoading?: boolean;
}

const ArvoButton = forwardRef<HTMLButtonElement, ArvoButtonProps>(
  function ArvoButton(
    {
      variant = 'primary',
      size = 'md',
      type = 'button',
      label,
      icon,
      isDisabled = false,
      isSelected: selectedProp,
      defaultSelected = false,
      isToggle = false,
      onSelectionChange,
      isFullWidth = false,
      isLoading = false,
      className,
      onClick,
      onKeyDown,
      ...rest
    },
    ref
  ) {
    const internalRef = useRef<HTMLButtonElement | null>(null);
    const [isSelected, setSelected] = useControllableState<boolean>(
      selectedProp,
      defaultSelected,
    );

    const classes = [
      'arvo-btn',
      `arvo-btn--${variant}`,
      `arvo-btn--${size}`,
      isFullWidth ? 'arvo-btn--full-width' : '',
      isLoading ? 'loading' : '',
      isSelected ? 'active' : '',
      className ?? '',
    ]
      .filter(Boolean)
      .join(' ');

    const blocked = isDisabled || isLoading;

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (blocked) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      if (isToggle) {
        const next = !isSelected;
        setSelected(next);
        onSelectionChange?.(next);
      }
      onClick?.(e);
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>) => {
      if (blocked && (e.key === 'Enter' || e.key === ' ')) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      onKeyDown?.(e);
    };

    // aria-pressed is rendered when the button is a toggle, OR when the consumer
    // explicitly opts in by passing `isSelected` (e.g. an active menu trigger).
    const showAriaPressed = isToggle || selectedProp !== undefined;
    const ariaPressedProp = showAriaPressed ? { 'aria-pressed': isSelected } : {};

    const mergeRefs = (node: HTMLButtonElement | null) => {
      internalRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    return (
      <button
        ref={mergeRefs}
        type={type}
        className={classes}
        disabled={isDisabled}
        aria-busy={isLoading ? true : undefined}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        {...ariaPressedProp}
        {...rest}
      >
        {icon && (
          <span
            className={`arvo-btn__ico o9con o9con-${icon}`}
            aria-hidden="true"
          />
        )}
        <span className="arvo-btn__lbl">{label}</span>
      </button>
    );
  }
);

export default ArvoButton;
export { ArvoButton };
